G3","positions":["EDG"]},{"id":"MID1","positions":["MID"]},{"id":"MID2","positions":["MID"]},{"id":"MID3","positions":["MID"]},{"id":"FLEX1","positions":["WFB","CTR","HLF","EDG","MID"]}],"entryPolicy":"before-first-kickoff","lockPolicy":"round-wide-v1","commerciallyApproved":false,"salaryUnit":"fantasy-dollars"},"scoringRules":{"beta":true,"slots":[{"id":"WFB1","positions":["WFB"]},{"id":"WFB2","positions":["WFB"]},{"id":"CTR1","positions":["CTR"]},{"id":"CTR2","positions":["CTR"]},{"id":"HLF1","positions":["HLF"]},{"id":"HLF2","positions":["HLF"]},{"id":"EDG1","positions":["EDG"]},{"id":"EDG2","positions":["EDG"]},{"id":"EDG3","positions":["EDG"]},{"id":"MID1","positions":["MID"]},{"id":"MID2","positions":["MID"]},{"id":"MID3","positions":["MID"]},{"id":"FLEX1","positions":["WFB","CTR","HLF","EDG","MID"]}],"sport":"nrl","title":"Docked NRL · event scoring","policy":["Event values reference NRL Fantasy 2026 guidelines, reviewed 22 October 2026. Docked retains its own lineup and lock rules; no captain, emergency or bench scoring is added.","Run and kick metres earn points only for complete groups of 10 and 30 respectively, calculated separately per match. Offloads to hand and ground are separate required statistics. One- and two-point field goals each earn 5 fantasy points.","Use source-defined turnover events once: do not add an intercept and a strip again when they are already in the turnover total. Missing event fields are unavailable, never automatically zero. Explicit confirmed DNP/bye remains distinct."],"version":"docked-nrl-events-v1","weights":{"goals":200,"tries":800,"errors":-200,"sinBins":-500,"tackles":100,"sendOffs":-1000,"trySaves":500,"runMetres":100,"turnovers":400,"fieldGoals":500,"kickMetres":100,"lineBreaks":400,"tryAssists":500,"kicksDefused":100,"tackleBreaks":200,"escapesInGoal":200,"fortyTwenties":400,"missedTackles":-200,"twentyForties":400,"forcedDropouts":200,"offloadsToHand":400,"lineBreakAssists":200,"offloadsToGround":200,"penaltiesConceded":-200,"sixAgainInfringements":-100},"positions":["WFB","CTR","HLF","EDG","MID"],"periodName":"round","correctionHours":72,"statisticGroups":{"runMetres":10,"kickMetres":30}},"fixtureId":"public-roster-practice-20261106-pool-v2:nrl:OPEN","addFixtureIds":[],"sourceReference":"Forward roster eligibility public-roster-practice-20261106-pool-v2; dormant source candidate SHA256 f436a9883a1ddda433fe81248533ad1d68d1aa02de8ca69d0863c465d8de60fc"}]}$packet$::jsonb;
  item jsonb;
  p jsonb;
  prior beta_fantasy.competitions;
  prior_map public_gameplay.rounds;
  new_rules jsonb;
  new_fixtures jsonb;
  target_player uuid;
  new_id uuid;
  version_id text := packet->>'version';
  expected_candidate_hash text := packet->>'candidateHash';
  closes timestamptz := (packet->>'closes')::timestamptz;
  original_function regprocedure := to_regprocedure('sports_feed.free_core_inventory(uuid,uuid)');
begin
  if clock_timestamp()>=(packet->>'sourceExpiry')::timestamptz or closes<=clock_timestamp() then
    raise exception 'Reviewed source or round expired';
  end if;
  if exists(select 1 from public_gameplay.policy where enabled)
    or exists(select 1 from public_gameplay.sports where visible or play_enabled)
    or exists(select 1 from public_gameplay.rounds where enabled)
    or exists(select 1 from private.feature_flags where key='registration' and enabled)
    or not exists(select 1 from commercial_billing.control where id and environment='commercial'
      and not sales_enabled and not issuance_enabled and not transfers_enabled and not gameplay_enabled)
  then raise exception 'Public and commercial switches must remain closed'; end if;
  if jsonb_array_length(packet->'overlays')<>49 or jsonb_array_length(packet->'rounds')<>6 then
    raise exception 'Unrecognised overlay scope';
  end if;

  for p in select value from jsonb_array_elements(packet->'overlays') loop
    target_player := (p->>'id')::uuid;
    if p->>'sport'='nfl' then
      if not exists(select 1 from beta_fantasy.players v
         left join sports_feed.free_core_roster r on r.player_id=v.id
         where v.id=target_player and v.sport='nfl' and v.status='active'
         and v.team=p#>>'{before,team}' and v.position=p#>>'{before,position}'
         and case when p#>>'{before,coreJoin}'='true'
           then r.active and r.season=packet->>'season' and r.valid_until>closes
             and r.eligible_positions=p#>'{before,positions}'
           else r.player_id is null end) then raise exception 'Reviewed NFL registry changed'; end if;
    elsif p->>'sport'='nrl' then
      if not exists(select 1 from credits_sandbox.nba_fixture_players v
         join sports_feed.free_core_roster_beta r on r.provider_player_id=v.id
         where v.identity->>'fixturePlayerId'=target_player::text
         and v.identity->>'sport'='nrl' and v.identity->>'status'='active'
         and credits_sandbox.is_roster_beta_player(v.identity)
         and v.identity->>'currentTeam'=p#>>'{before,team}'
         and v.identity->>'position'=p#>>'{before,position}'
         and r.sport='nrl' and r.season=packet->>'season' and r.active and r.valid_until>closes
         and r.source_hash=v.identity->'rosterBeta'->>'sourceHash'
         and r.eligible_positions=p#>'{before,positions}') then raise exception 'Reviewed NRL registry changed'; end if;
    else raise exception 'Unexpected overlay sport'; end if;

    insert into sports_feed.public_free_core_overlays(
      version,player_id,sport,team,position,eligible_positions,name,colour,jersey_number,
      source_hash,candidate_hash,valid_until
    ) values(version_id,target_player,p->>'sport',p#>>'{after,team}',p#>>'{after,position}',
      p#>'{after,positions}',p#>>'{after,name}',p#>>'{after,colour}',
      (p#>>'{after,jerseyNumber}')::integer,p#>>'{after,sourceHash}',expected_candidate_hash,closes)
    on conflict on constraint public_free_core_overlays_pkey do nothing;
    if not exists(select 1 from sports_feed.public_free_core_overlays o where
      o.version=version_id and o.player_id=(p->>'id')::uuid and o.sport=p->>'sport'
      and o.team=p#>>'{after,team}' and o.position=p#>>'{after,position}'
      and o.eligible_positions=p#>'{after,positions}' and o.name=p#>>'{after,name}'
      and o.colour=p#>>'{after,colour}' and o.jersey_number is not distinct from (p#>>'{after,jerseyNumber}')::integer
      and o.source_hash=p#>>'{after,sourceHash}' and o.candidate_hash=expected_candidate_hash and o.valid_until=closes
    ) then raise exception 'Overlay replay conflicts with reviewed values'; end if;
  end loop;
  if (select count(*) from sports_feed.public_free_core_overlays where version=version_id)<>49 then
    raise exception 'Overlay version contains extra players';
  end if;

  for item in select value from jsonb_array_elements(packet->'rounds') loop
    select * into strict prior from beta_fantasy.competitions where id=(item->>'previousId')::uuid for update;
    select * into strict prior_map from public_gameplay.rounds where competition_id=prior.id for update;
    if prior.sport<>item->>'sport' or prior.name<>item->>'name' or prior.season<>packet->>'season'
      or prior.round<>2 or prior.locks_at<>closes or prior.scored_at is not null
      or prior.rules is distinct from item->'previousRules' or prior.awards<>'[]'::jsonb or prior.prize<>'No cash prize'
      or prior_map.enabled or prior_map.rules_hash<>md5(prior.rules::text) or prior_map.sport<>prior.sport
      or prior_map.fixture_kind<>'practice' or prior_map.source_reference<>item->>'previousSource'
      or jsonb_array_length(prior_map.fixtures)<>1
      or (prior_map.fixtures->0)-'playerIds' is distinct from item->'previousFixtureMetadata'
      or (select md5(string_agg(id,',' order by id collate "C"))
        from jsonb_array_elements_text(prior_map.fixtures#>'{0,playerIds}') p(id))
          is distinct from item->>'previousFixtureIdsHash'
      or not exists(select 1 from beta_fantasy.lineup_configurations f
         where f.version=prior.rules->>'lineup_version' and f.configuration=item->'lineup')
      or not exists(select 1 from beta_fantasy.scoring_rules s where s.id=prior.scoring_id and s.rules=item->'scoringRules')
    then raise exception 'Existing saved round or rules changed'; end if;

    new_id := (item->>'id')::uuid;
    if exists(select 1 from beta_fantasy.competitions where sport=prior.sport and season=prior.season
      and round=3 and rules->>'mode'=prior.rules->>'mode' and id<>new_id)
    then raise exception 'Replacement round number already used'; end if;
    if exists(select 1 from beta_fantasy.entries where competition_id in (prior.id,new_id))
      or exists(select 1 from beta_fantasy.round_drafts where competition_id in (prior.id,new_id))
      or exists(select 1 from beta_fantasy.entry_revisions where competition_id in (prior.id,new_id))
      or exists(select 1 from beta_fantasy.slot_locks where competition_id in (prior.id,new_id))
      or exists(select 1 from beta_fantasy.results where competition_id in (prior.id,new_id))
      or exists(select 1 from sports_feed.sport_rounds where competition_id in (prior.id,new_id))
      or exists(select 1 from beta_fantasy.production_rounds where competition_id in (prior.id,new_id))
    then raise exception 'Previous or replacement round already has gameplay or beta exposure'; end if;

    new_rules := prior.rules || jsonb_build_object('public_template_version',version_id,
      'free_core_roster_version',version_id,'commercial_inventory_policy','commercial-owned-v1');
    new_fixtures := jsonb_set(jsonb_set(prior_map.fixtures,'{0,fixtureId}',to_jsonb(item->>'fixtureId')),
      '{0,playerIds}',(select jsonb_agg(id order by id collate "C") from (
        select id from jsonb_array_elements_text(prior_map.fixtures#>'{0,playerIds}') p(id)
        union select id from jsonb_array_elements_text(item->'addFixtureIds') p(id)
      ) q));
    insert into beta_fantasy.competitions(id,name,sport,season,round,opens_at,locks_at,rules,scoring_id,awards,prize)
      values(new_id,prior.name,prior.sport,prior.season,3,prior.opens_at,prior.locks_at,new_rules,prior.scoring_id,prior.awards,prior.prize)
      on conflict(id) do nothing;
    if not exists(select 1 from beta_fantasy.competitions c where c.id=new_id and c.rules=new_rules
      and c.sport=prior.sport and c.season=prior.season and c.round=3 and c.scored_at is null
      and c.name=prior.name and c.opens_at=prior.opens_at and c.locks_at=prior.locks_at
      and c.scoring_id=prior.scoring_id and c.awards=prior.awards and c.prize=prior.prize)
    then raise exception 'Replacement competition conflicts with reviewed values'; end if;
    insert into public_gameplay.rounds(competition_id,sport,enabled,rules_hash,fixtures,fixture_kind,source_reference)
      values(new_id,prior.sport,false,md5(new_rules::text),new_fixtures,'practice',item->>'sourceReference')
      on conflict(competition_id) do nothing;
    if not exists(select 1 from public_gameplay.rounds r where r.competition_id=new_id
      and not r.enabled and r.sport=prior.sport and r.rules_hash=md5(new_rules::text)
      and r.fixtures=new_fixtures and r.fixture_kind='practice' and r.source_reference=item->>'sourceReference')
    then raise exception 'Replacement binding conflicts with reviewed values'; end if;
  end loop;
  if (select count(*) from public_gameplay.rounds r join beta_fantasy.competitions c on c.id=r.competition_id
      where c.rules->>'public_template_version'=version_id)<>6
    then raise exception 'Unexpected replacement round count'; end if;

  if to_regprocedure('sports_feed.free_core_inventory_before_public_pool_v2(uuid,uuid)') is null then
    if original_function is null or pg_get_functiondef(original_function) not like '%free_core_inventory_before_roster_beta%'
      or pg_get_functiondef(original_function) not like '%public_gameplay.session_allowed()%'
    then raise exception 'Reviewed Free Core reader changed'; end if;
    alter function sports_feed.free_core_inventory(uuid,uuid) rename to free_core_inventory_before_public_pool_v2;
  elsif original_function is null or pg_get_functiondef(original_function) not like '%public-roster-practice-20261106-pool-v2%' then
    raise exception 'Existing Free Core wrapper differs from reviewed transition';
  end if;
end $forward$;

create or replace function sports_feed.free_core_inventory(u uuid,cid uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare base jsonb:=coalesce(sports_feed.free_core_inventory_before_public_pool_v2(u,cid),'[]');
  answer jsonb;
begin
  if current_setting('docked.public_gameplay',true) is distinct from 'enabled'
    or u is null or u is distinct from auth.uid() or cid not in ('6c78eac7-561d-5451-a34d-6d909eb8dcf0'::uuid,'2b282c96-93f1-54e6-a6ea-ba750de4d89d'::uuid,'690eb6d5-287c-5f5b-a5e6-0c336db4e371'::uuid,'e887078d-b43a-523e-a6fc-bfc3de00a32f'::uuid,'8cf2dcaa-1b33-5b56-a79e-650b7e4efb08'::uuid,'c2036eab-965b-5928-a0d8-4e239cde6f52'::uuid)
    or not public_gameplay.round_allowed(cid) then return base; end if;

  with overlay as materialized (
    select o.*,c.season from sports_feed.public_free_core_overlays o
    join beta_fantasy.competitions c on c.id=cid and c.sport=o.sport
    join sports_feed.free_core_programmes g on g.sport=c.sport and g.enabled
      and c.rules->>'free_core_policy'=g.version
    join beta_fantasy.lineup_configurations f on f.version=c.rules->>'lineup_version'
    where o.version=c.rules->>'free_core_roster_version'
      and o.version='public-roster-practice-20261106-pool-v2'
      and o.candidate_hash='f436a9883a1ddda433fe81248533ad1d68d1aa02de8ca69d0863c465d8de60fc'
      and c.rules->>'commercial_inventory_policy'='commercial-owned-v1'
      and c.scored_at is null and c.locks_at>clock_timestamp() and o.valid_until>clock_timestamp()
      and not exists(select 1 from jsonb_array_elements_text(o.eligible_positions) e(pos)
        where not exists(select 1 from jsonb_array_elements(f.configuration->'slots') s where s->'positions' ? e.pos))
  ), decorated as (
    select coalesce(b.value,'{}') || jsonb_build_object(
      'id',md5('public-free-core-v1:'||u::text||':'||o.player_id::text)::uuid,
      'player_id',o.player_id,'canonical_player_id',o.player_id,'owner_id',u,'sport',o.sport,
      'name',o.name,'team',o.team,'colour',o.colour,'season',o.season,'position',o.position,
      'eligible_positions',o.eligible_positions,'tier','CORE','serial',null,'tradeable',false,
      'listed',false,'status','active','multiplier',1,'multiplierTenths',10,
      'inventory_source','public-free-core-v1','collectible_owned',false,
      'availability_reason','Free Core gameplay eligibility; not an owned collectible',
      'eligible_competition_ids',jsonb_build_array(cid),'source_hash',o.source_hash,
      'verifiedJerseyNumber',o.jersey_number
    ) card from overlay o
    left join lateral (select value from jsonb_array_elements(base) b
      where value->>'player_id'=o.player_id::text limit 1) b on true
  )
  select coalesce((select jsonb_agg(value) from jsonb_array_elements(base) b
    where not exists(select 1 from overlay o where o.player_id::text=b.value->>'player_id')),'[]')
    || coalesce((select jsonb_agg(card) from decorated),'[]') into answer;
  return answer;
end $$;
revoke all on function sports_feed.free_core_inventory(uuid,uuid),
  sports_feed.free_core_inventory_before_public_pool_v2(uuid,uuid)
  from public,anon,authenticated,service_role,docked_app,docked_beta_app,docked_commercial_app;
commit;
